-93b6-386a834acc07", "type": "concept", "title": "Expected return"}, {"id": "6eb1a456-cd3e-4581-b2f8-4c6898747a36", "type": "concept", "title": "Risk premium"}, {"id": "e7da958e-71dc-457b-84cc-82f645512610", "type": "concept", "title": "Diversifiable versus systematic risk preview"}], "description": "Every finance decision asks what return is required for bearing risk."}]}, {"id": "f979b580-8ab9-4ce2-b6bc-bb665beeb63d", "type": "topic", "title": "The Financial System, Capital Markets, and Institutions", "description": "This topic explains how savers, borrowers, firms, intermediaries, and markets connect in the real economy.", "children": [{"id": "d2379d95-55f3-4b30-8957-5b21169793de", "type": "subtopic", "title": "Market participants", "children": [{"id": "44b20081-efb0-4f10-abcb-d88069476454", "type": "concept", "title": "Households and firms"}, {"id": "6b5bc8c1-e94d-4805-9e83-e93a57d18ff6", "type": "concept", "title": "Banks, insurers, and asset managers"}, {"id": "1ad0bba9-ee10-400a-8df4-f8718770392d", "type": "concept", "title": "Governments and central banks"}], "description": "Students learn who supplies capital, who demands it, and who intermediates."}, {"id": "ba0cea5d-4bc2-47e8-a14c-dc59ee1ee7be", "type": "subtopic", "title": "Capital markets", "children": [{"id": "3c8624db-3856-4581-8e30-6ef6ef67525a", "type": "concept", "title": "Primary and secondary markets"}, {"id": "a418b991-0d63-43a7-855f-d6dd3c56a63a", "type": "concept", "title": "Money and capital markets"}, {"id": "38402da6-abd7-4dd6-bc81-222372065674", "type": "concept", "title": "Public versus private markets"}], "description": "Markets turn financial claims into prices and liquidity."}, {"id": "5f78a6bb-4996-4b18-9208-599b94949e89", "type": "subtopic", "title": "Financial intermediation", "children": [{"id": "7acff093-a311-4272-9058-8617fb23206b", "type": "concept", "title": "Information asymmetry"}, {"id": "6f0178e6-d0b4-475f-a198-899319be4b03", "type": "concept", "title": "Liquidity transformation"}, {"id": "7ff88f86-0c30-48a4-a819-7a5a1a5c1e1e", "type": "concept", "title": "Systemic risk preview"}], "description": "Institutions reduce frictions but also introduce risk and regulation."}]}, {"id": "dcff8670-755f-478e-b7ef-f7cfba96fc59", "type": "topic", "title": "Financial Statements, Cash Flow, and Return Measurement", "description": "Students learn the accounting and cash-flow language needed before valuing securities or projects.", "children": [{"id": "16bd9155-c6d5-40a5-882a-8f79695e8519", "type": "subtopic", "title": "Statement basics", "children": [{"id": "c54e2c30-96b7-4e2c-b30e-8bb02b62428c", "type": "concept", "title": "Income statement"}, {"id": "6458d16b-14f7-40d3-b505-7a037a1f3a78", "type": "concept", "title": "Balance sheet"}, {"id": "b34199a2-9966-45a9-862f-b9c936bf53ba", "type": "concept", "title": "Cash flow statement"}], "description": "Finance students need enough accounting to identify real cash economics."}, {"id": "8e661c13-d2f9-4059-835d-2f1e49f464e2", "type": "subtopic", "title": "Free cash flow", "children": [{"id": "9ac01db6-e647-4739-b132-22cac347e994", "type": "concept", "title": "Operating cash flow"}, {"id": "dcfec9ac-3934-4fd2-95a6-c54e343aa4f4", "type": "concept", "title": "Capital expenditures"}, {"id": "9a860b4c-0017-4d7a-98fc-7590fbfeb48e", "type": "concept", "title": "Working capital changes"}], "description": "Valuation and capital budgeting depend on cash available after reinvestment."}, {"id": "6603944d-60c7-4710-a524-3e637b4ba1a2", "type": "subtopic", "title": "Performance measures", "children": [{"id": "f0966357-0995-46b6-9f2b-7b27bc4ce5dd", "type": "concept", "title": "Margins and turnover"}, {"id": "0e25672b-f223-4a90-ad80-565663a971ab", "type": "concept", "title": "ROA, ROE, and ROIC"}, {"id": "1f62ab9d-726f-46eb-9ce4-a4059d815c2e", "type": "concept", "title": "Accounting quality caveats"}], "description": "Students learn to evaluate business performance across profitability, efficiency, and returns."}]}, {"id": "23b4c26b-4ba8-40f8-948d-58d0dc4be824", "type": "topic", "title": "Time Value of Money and Present Value Logic", "description": "This core module teaches how to compare cash flows occurring at different dates.", "children": [{"id": "6ec9a2ca-47f9-4836-9dda-e5e7b3786ec8", "type": "subtopic", "title": "Compounding and discounting", "children": [{"id": "ac4fe25e-5de6-4866-94db-83d6290c718c", "type": "concept", "title": "Future value"}, {"id": "88816912-ee81-43a0-bffb-c98850b61a9a", "type": "concept", "title": "Present value"}, {"id": "ba4f234c-53d4-4dc8-839c-a330f45e4b31", "type": "concept", "title": "Compounding frequency"}], "description": "Money today is not the same as money later because capital has opportunity cost."}, {"id": "8f4589c3-b8c9-4b07-b0cc-49fdb1bb954b", "type": "subtopic", "title": "Annuities and perpetuities", "children": [{"id": "f176d6c9-e8b9-4e8e-8747-7420f436efad", "type": "concept", "title": "Ordinary annuities"}, {"id": "2195026f-b936-41cb-bc5e-2d9c4936aa92", "type": "concept", "title": "Growing annuities"}, {"id": "04cf0265-ca27-4998-90b3-cbdad8a23959", "type": "concept", "title": "Perpetuities and growing perpetuities"}], "description": "Common cash-flow patterns can be valued efficiently."}, {"id": "6c7c4518-a213-4d21-affd-07007922c274", "type": "subtopic", "title": "Applications", "children": [{"id": "3e132d1a-38ff-40e3-96a8-67688fa6c8f4", "type": "concept", "title": "Loan amortization"}, {"id": "bdbbf3e3-6c91-4e4d-8689-c0fe91e0056c", "type": "concept", "title": "Savings and retirement planning"}, {"id": "1504ae57-79e4-465a-9f23-ead886399a38", "type": "concept", "title": "Project cash-flow timing"}], "description": "TVM is the arithmetic beneath loans, bonds, projects, retirement, and valuation."}]}, {"id": "da28567c-8903-410d-9e34-eb82498923c1", "type": "topic", "title": "Interest Rates, Yield Curves, Inflation, and No-Arbitrage Intuition", "description": "Students connect discount rates to market prices, inflation expectations, and the idea that identical cash flows should have identical value.", "children": [{"id": "2125d7c9-acc8-4cc4-bbae-960d300dc60c", "type": "subtopic", "title": "Interest-rate building blocks", "children": [{"id": "81209cac-0fa3-4e68-918d-d9d690815536", "type": "concept", "title": "Real and nominal rates"}, {"id": "6a33d52e-cddf-4938-8ec0-9895ffc5d2a8", "type": "concept", "title": "Inflation expectations"}, {"id": "5addd3ab-51ed-4c24-a5fc-cdf8a3da76ca", "type": "concept", "title": "Default and liquidity premiums"}], "description": "Students learn why different cash flows require different discount rates."}, {"id": "8125bbde-a089-4805-aec8-bfe4765e871e", "type": "subtopic", "title": "Yield curve", "children": [{"id": "d1f9275a-6725-42bf-9ef0-d6c5902a5cbb", "type": "concept", "title": "Spot rates"}, {"id": "5e9ce017-c8b4-42eb-ab81-d908837da51f", "type": "concept", "title": "Forward rates"}, {"id": "93eb7bc5-d8b3-48d0-b3b5-928492ba7fae", "type": "concept", "title": "Upward and inverted yield curves"}], "description": "The term structure summarizes market prices for money across time."}, {"id": "4c49b903-aec0-4bb0-8621-ed822f58ea19", "type": "subtopic", "title": "No-arbitrage logic", "children": [{"id": "6f58c635-e3a5-4f57-8f8d-bc8028c8bffd", "type": "concept", "title": "Law of one price"}, {"id": "838afbe1-f668-4a22-a6f5-c54afbe84cfd", "type": "concept", "title": "Replicating cash flows"}, {"id": "d813e2c5-2540-4f65-8075-480b4c62ed37", "type": "concept", "title": "Arbitrage examples"}], "description": "No-arbitrage is the discipline that prevents inconsistent pricing."}]}, {"id": "bb4812e8-e035-4a49-8523-778f1cc1ecf4", "type": "topic", "title": "Bond Pricing, Yields, Duration, and Fixed-Income Risk", "description": "This topic develops bond valuation and the risks created by changing rates and credit conditions.", "children": [{"id": "3d106ae6-003c-4581-a50a-f686838b3301", "type": "subtopic", "title": "Bond valuation", "children": [{"id": "6294cbee-8f35-4f61-8a0e-28ebc9133d52", "