5b5", "type": "concept", "title": "Efficient frontier"}], "description": "Students learn the logic of efficient portfolios."}, {"id": "13e1bfa6-5771-4ad0-97a8-236ece6ad230", "type": "subtopic", "title": "Investor objectives", "children": [{"id": "b7b73305-9ded-43c2-8939-24299a545071", "type": "concept", "title": "Risk aversion"}, {"id": "6a80ff4b-3535-43cd-b3aa-e727aebcc488", "type": "concept", "title": "Investment horizon"}, {"id": "70041459-e65a-44e5-a984-a937055aae0e", "type": "concept", "title": "Liquidity and tax constraints"}], "description": "Portfolio choice depends on goals, constraints, and risk tolerance."}]}, {"id": "4320159b-0b03-4a42-9900-4f93973bbb7e", "type": "topic", "title": "CAPM, Factor Models, and Asset Pricing Foundations", "description": "Students learn equilibrium and factor-based approaches to expected return.", "children": [{"id": "b19073b1-f3e0-4ff7-a259-8c082dc3ca76", "type": "subtopic", "title": "CAPM", "children": [{"id": "5dcfd682-6ce0-4ebd-954c-a0252bc6ff08", "type": "concept", "title": "Beta"}, {"id": "6e3634b2-f25b-4dd2-8f3e-f4ae97fdba8e", "type": "concept", "title": "Security market line"}, {"id": "00475cd8-63cd-4114-80cf-64e06830182c", "type": "concept", "title": "Alpha and abnormal return"}], "description": "CAPM links expected return to exposure to market risk."}, {"id": "04b7b1de-eced-403f-bbf6-a9d66c79b8d0", "type": "subtopic", "title": "Factor models", "children": [{"id": "84789f3d-8532-4b35-9d71-e9bfa46e0cf0", "type": "concept", "title": "Size, value, momentum, profitability, and investment factors"}, {"id": "7953ae45-ea72-476c-add7-ccb1a510ce9f", "type": "concept", "title": "Factor exposures"}, {"id": "9d246d20-92f8-4fb3-a70b-d3f803bd6d87", "type": "concept", "title": "Limits of factor models"}], "description": "Modern investing often explains returns with multiple systematic factors."}, {"id": "a1c48fd8-ef7b-4319-ac3d-6fd2a4bd78d1", "type": "subtopic", "title": "Asset pricing interpretation", "children": [{"id": "a6451365-