set
  title = 'Foundations of Finance / Principles of Finance',
  goal = 'Foundations of Finance / Principles of Finance',
  summary = 'The workbook syllabus is sufficient for a conventional principles course. For a comprehensive foundation, this version keeps the core and adds financial statements, no-arbitrage intuition, behavioral finance, governance, risk management, fintech, sustainable finance, ethics, and a capstone finance decision case.',
  data = $fofjson${"slug": "foundations-of-finance-principles-of-finance", "title": "Foundations of Finance / Principles of Finance", "description": "The workbook syllabus is sufficient for a conventional principles course. For a comprehensive foundation, this version keeps the core and adds financial statements, no-arbitrage intuition, behavioral finance, governance, risk management, fintech, sustainable finance, ethics, and a capstone finance decision case.", "topics": [{"id": "e995b6ee-64fe-49d8-b6d8-30bacbd632eb", "type": "topic", "title": "Finance as a Discipline: Value, Risk, and Capital Allocation", "description": "Students learn finance as a framework for moving money through time, allocating scarce capital, and making risk-aware decisions.", "children": [{"id": "f986ccc4-7a9c-433a-917d-49b47634c8f0", "type": "subtopic", "title": "Core finance questions", "children": [{"id": "6518594a-1ae5-4e8b-8c2d-4ce5e782e63f", "type": "concept", "title": "What investments should be made?"}, {"id": "417fe442-cb25-460c-87a8-aa3cc545de1b", "type": "concept", "title": "How should they be financed?"}, {"id": "94d4366b-c9d5-49fb-b0d3-49ff1219b320", "type": "concept", "title": "How should risk and rewards be shared?"}], "description": "The point is to see finance as disciplined decision-making under time and uncertainty."}, {"id": "5d27cc5c-bf1f-43d3-b6a7-65691491b44a", "type": "subtopic", "title": "Value creation", "children": [{"id": "e2a18c49-244c-4fac-8eef-1a34a601ecda", "type": "concept", "title": "Cash flow versus accounting profit"}, {"id": "d0bffacb-e11e-4d3f-a51b-ee995221c728", "type": "concept", "title": "Opportunity cost"}, {"id": "5b688f7b-f62a-4ef0-928c-d629ee49facc", "type": "concept", "title": "Economic value added intuition"}], "description": "Students learn that finance is ultimately about creating value, not just moving money."}, {"id": "da6402d6-bc14-43cc-8e1d-5c3f4fce1c9e", "type": "subtopic", "title": "Risk-return tradeoff", "children": [{"id": "f113c2f2-0508-4133-93b6-386a834acc07", "type": "concept", "title": "Expected return"}, {"id": "6eb1a456-cd3e-4581-b2f8-4c6898747a36", "type": "concept", "title": "Risk premium"}, {"id": "e7da958e-71dc-457b-84cc-82f645512610", "type": "concept", "title": "Diversifiable versus systematic risk preview"}], "description": "Every finance decision asks what return is required for bearing risk."}]}, {"id": "f979b580-8ab9-4ce2-b6bc-bb665beeb63d", "type": "topic", "title": "The Financial System, Capital Markets, and Institutions", "description": "This topic explains how savers, borrowers, firms, intermediaries, and markets connect in the real economy.", "children": [{"id": "d2379d95-55f3-4b30-8957-5b21169793de", "type": "subtopic", "title": "Market participants", "children": [{"id": "44b20081-efb0-4f10-abcb-d88069476454", "type": "concept", "title": "Households and firms"}, {"id": "6b5bc8c1-e94d-4805-9e83-e93a57d18ff6", "type": "concept", "title": "Banks, insurers, and asset managers"}, {"id": "1ad0bba9-ee10-400a-8df4-f8718770392d", "type": "concept", "title": "Governments and central banks"}], "description": "Students learn who supplies capital, who demands it, and who intermediates."}, {"id": "ba0cea5d-4bc2-47e8-a14c-dc59ee1ee7be", "type": "subtopic", "title": "Capital markets", "children": [{"id": "3c8624db-3856-4581-8e30-6ef6ef67525a", "type": "concept", "title": "Primary and secondary markets"}, {"id": "a418b991-0d63-43a7-855f-d6dd3c56a63a", "type": "concept", "title": "Money and capital markets"}, {"id": "38402da6-abd7-4dd6-bc81-222372065674", "type": "concept", "title": "Public versus private markets"}], "description": "Markets turn financial claims into prices and liquidity."}, {"id": "5f78a6bb-4996-4b18-9208-599b94949e89", "type": "subtopic", "title": "Financial intermediation", "children": [{"id": "7acff093-a311-4272-9058-8617fb23206b", "type": "concept", "title": "Information asymmetry"}, {"id": "6f0178e6-d0b4-475f-a198-899319be4b03", "type": "concept", "title": "Liquidity transformation"}, {"id": "7ff88f86-0c30-48a4-a819-7a5a1a5c1e1e", "type": "concept", "title": "Systemic risk preview"}], "description": "Institutions reduce frictions but also introduce risk and regulation."}]}, {"id": "dcff8670-755f-478e-b7ef-f7cfba96fc59", "type": "topic", "title": "Financial Statements, Cash Flow, and Return Measurement", "description": "Students learn the accounting and cash-flow language needed before valuing securities or projects.", "children": [{"id": "16bd9155-c6d5-40a5-882a-8f79695e8519", "type": "subtopic", "title": "Statement basics", "children": [{"id": "c54e2c30-96b7-4e2c-b30e-8bb02b62428c", "type": "concept", "title": "Income statement"}, {"id": "6458d16b-14f7-40d3-b505-7a037a1f3a78", "type": "concept", "title": "Balance sheet"}, {"id": "b34199a2-9966-45a9-862f-b9c936bf53ba", "type": "concept", "title": "Cash flow statement"}], "description": "Finance students need enough accounting to identify real cash economics."}, {"id": "8e661c13-d2f9-4059-835d-2f1e49f464e2", "type": "subtopic", "title": "Free cash flow", "children": [{"id": "9ac01db6-e647-4739-b132-22cac347e994", "type": "concept", "title": "Operating cash flow"}, {"id": "dcfec9ac-3934-4fd2-95a6-c54e343aa4f4", "type": "concept", "title": "Capital expenditures"}, {"id": "9a860b4c-0017-4d7a-98fc-7590fbfeb48e", "type": "concept", "title": "Working capital changes"}], "description": "Valuation and capital budgeting depend on cash available after reinvestment."}, {"id": "6603944d-60c7-4710-a524-3e637b4ba1a2", "type": "subtopic", "title": "Performance measures", "children": [{"id": "f0966357-0995-46b6-9f2b-7b27bc4ce5dd", "type": "concept", "title": "Margins and turnover"}, {"id": "0e25672b-f223-4a90-ad80-565663a971ab", "type": "concept", "title": "ROA, ROE, and ROIC"}, {"id": "1f62ab9d-726f-46eb-9ce4-a4059d815c2e", "type": "concept", "title": "Accounting quality caveats"}], "description": "Students learn to evaluate business performance across profitability, efficiency, and returns."}]}, {"id": "23b4c26b-4ba8-40f8-948d-58d0dc4be824", "type": "topic", "title": "Time Value of Money and Present Value Logic", "description": "This core module teaches how to compare cash flows occurring at different dates.", "children": [{"id": "6ec9a2ca-47f9-4836-9dda-e5e7b3786ec8", "type": "subtopic", "title": "Compounding and discounting", "children": [{"id": "ac4fe25e-5de6-4866-94db-83d6290c718c", "type": "concept", "title": "Future value"}, {"id": "88816912-ee81-43a0-bffb-c98850b61a9a", "type": "concept", "title": "Present value"}, {"id": "ba4f234c-53d4-4dc8-839c-a330f45e4b31", "type": "concept", "title": "Compounding frequency"}], "description": "Money today is not the same as money later because capital has opportunity cost."}, {"id": "8f4589c3-b8c9-4b07-b0cc-49fdb1bb954b", "type": "subtopic", "title": "Annuities and perpetuities", "children": [{"id": "f176d6c9-e8b9-4e8e-8747-7420f436efad", "type": "concept", "title": "Ordinary annuities"}, {"id": "2195026f-b936-41cb-bc5e-2d9c4936aa92", "type": "concept", "title": "Growing annuities"}, {"id": "04cf0265-ca27-4998-90b3-cbdad8a23959", "type": "concept", "title": "Perpetuities and growing perpetuities"}], "description": "Common cash-flow patterns can be valued efficiently."}, {"id": "6c7c4518-a213-4d21-affd-07007922c274", "type": "subtopic", "title": "Applications", "children": [{"id": "3e132d1a-38ff-40e3-96a8-67688fa6c8f4", "type": "concept", "title": "Loan amortization"}, {"id": "bdbbf3e3-6c91-4e4d-8689-c0fe91e0056c", "type": "concept", "title": "Savings and retirement planning"}, {"id": "1504ae57-79e4-465a-9f23-ead886399a38", "type": "concept", "title": "Project cash-flow timing"}], "description": "TVM is the arithmetic beneath loans, bonds, projects, retirement, and valuation."}]}, {"id": "da28567c-8903-410d-9e34-eb82498923c1", "type": "topic", "title": "Interest Rates, Yield Curves, Inflation, and No-Arbitrage Intuition", "description": "Students connect discount rates to market prices, inflation expectations, and the idea that identical cash flows should have identical value.", "children": [{"id": "2125d7c9-acc8-4cc4-bbae-960d300dc60c", "type": "subtopic", "title": "Interest-rate building blocks", "children": [{"id": "81209cac-0fa3-4e68-918d-d9d690815536", "type": "concept", "title": "Real and nominal rates"}, {"id": "6a33d52e-cddf-4938-8ec0-9895ffc5d2a8", "type": "concept", "title": "Inflation expectations"}, {"id": "5addd3ab-51ed-4c24-a5fc-cdf8a3da76ca", "type": "concept", "title": "Default and liquidity premiums"}], "description": "Students learn why different cash flows require different discount rates."}, {"id": "8125bbde-a089-4805-aec8-bfe4765e871e", "type": "subtopic", "title": "Yield curve", "children": [{"id": "d1f9275a-6725-42bf-9ef0-d6c5902a5cbb", "type": "concept", "title": "Spot rates"}, {"id": "5e9ce017-c8b4-42eb-ab81-d908837da51f", "type": "concept", "title": "Forward rates"}, {"id": "93eb7bc5-d8b3-48d0-b3b5-928492ba7fae", "type": "concept", "title": "Upward and inverted yield curves"}], "description": "The term structure summarizes market prices for money across time."}, {"id": "4c49b903-aec0-4bb0-8621-ed822f58ea19", "type": "subtopic", "title": "No-arbitrage logic", "children": [{"id": "6f58c635-e3a5-4f57-8f8d-bc8028c8bffd", "type": "concept", "title": "Law of one price"}, {"id": "838afbe1-f668-4a22-a6f5-c54afbe84cfd", "type": "concept", "title": "Replicating cash flows"}, {"id": "d813e2c5-2540-4f65-8075-480b4c62ed37", "type": "concept", "title": "Arbitrage examples"}], "description": "No-arbitrage is the discipline that prevents inconsistent pricing."}]}, {"id": "bb4812e8-e035-4a49-8523-778f1cc1ecf4", "type": "topic", "title": "Bond Pricing, Yields, Duration, and Fixed-Income Risk", "description": "This topic develops bond valuation and the risks created by changing rates and credit conditions.", "children": [{"id": "3d106ae6-003c-4581-a50a-f686838b3301", "type": "subtopic", "title": "Bond valuation", "children": [{"id": "6294cbee-8f35-4f61-8a0e-28ebc9133d52", "type": "concept", "title": "Coupon bonds and zero-coupon bonds"}, {"id": "59c4aaa8-6084-41b4-b3ac-6447525f6fa9", "type": "concept", "title": "Yield to maturity"}, {"id": "d7636ed8-8c0c-487f-936a-968502a1265d", "type": "concept", "title": "Current yield and realized return"}], "description": "Students price promised fixed-income cash flows and understand yield measures."}, {"id": "0faf8cc5-4657-44cd-b845-72bfdf7e0bea", "type": "subtopic", "title": "Interest-rate sensitivity", "children": [{"id": "9a7d018c-57bc-4f99-a8e2-b03275bbb671", "type": "concept", "title": "Duration"}, {"id": "05c9668d-11c9-443c-af62-f72fbac435a4", "type": "concept", "title": "Convexity"}, {"id": "9df98128-7c2f-4cd7-afdd-f04576b104e6", "type": "concept", "title": "Immunization intuition"}], "description": "Bond prices move when rates move."}, {"id": "81629e71-6f8b-4ab7-af96-b9e499b13ea0", "type": "subtopic", "title": "Credit and liquidity risk", "children": [{"id": "274ae680-78bf-4f2a-b4b4-f4b809084317", "type": "concept", "title": "Credit spreads"}, {"id": "9422f95e-c13c-4a20-ac81-969adecce737", "type": "concept", "title": "Ratings and default risk"}, {"id": "a2b2e363-bec9-44a5-a4b8-69f74b6a1bc5", "type": "concept", "title": "Callable and embedded-option features"}], "description": "Fixed income is not risk-free unless the borrower and market conditions justify it."}]}, {"id": "6c76d69b-bda7-40f2-ad84-4cd4654d362a", "type": "topic", "title": "Stock Valuation Models and Equity Fundamentals", "description": "Students learn how equity value connects to dividends, cash flows, growth, and market expectations.", "children": [{"id": "f7155e50-472a-4c3a-b819-899e73e3cf3e", "type": "subtopic", "title": "Dividend and cash-flow models", "children": [{"id": "f19bc117-e4a4-4753-a271-372c166e228e", "type": "concept", "title": "Dividend discount model"}, {"id": "5ef7f53b-a4cf-49d7-8637-45a1db43123d", "type": "concept", "title": "Free cash flow to equity"}, {"id": "180d3883-e942-4408-aa80-213e356128fc", "type": "concept", "title": "Terminal value"}], "description": "Equity value reflects claims on uncertain future cash flows."}, {"id": "48b6e9e1-0dc5-4033-9805-9287bc3847a6", "type": "subtopic", "title": "Growth and profitability", "children": [{"id": "e3f47003-0b28-4ceb-b6c8-a4deae9af963", "type": "concept", "title": "Retention and payout"}, {"id": "9405cf88-ed26-44cc-bd1d-7b6912880c1a", "type": "concept", "title": "ROE and sustainable growth"}, {"id": "b9dddcc6-a7c7-49bb-915d-8fbd50010e23", "type": "concept", "title": "Competitive advantage period"}], "description": "Good valuation separates growth that creates value from growth that consumes capital."}, {"id": "d6de31fe-e930-4e6e-8d09-807a08e8c097", "type": "subtopic", "title": "Relative valuation", "children": [{"id": "b8f42032-efce-4695-9685-2fe3dbb4174b", "type": "concept", "title": "P/E, EV/EBITDA, and price/book"}, {"id": "76af5222-6e9b-4aa8-a404-d565a81c719d", "type": "concept", "title": "Peer selection"}, {"id": "72f63563-d7c2-4c52-9022-2b240a272806", "type": "concept", "title": "Multiple drivers and normalization"}], "description": "Students learn when market multiples are useful and when they mislead."}]}, {"id": "cf9e8b77-cf67-4518-930e-5113e53dbbd0", "type": "topic", "title": "Risk and Return Measurement", "description": "Students quantify historical and expected return, volatility, downside risk, and risk premia.", "children": [{"id": "c7791161-fedc-4db9-a46c-362a6f71cd39", "type": "subtopic", "title": "Return measurement", "children": [{"id": "63d0ada7-619e-4162-8de3-6160d7251410", "type": "concept", "title": "Arithmetic and geometric returns"}, {"id": "ec543b8b-a72d-4d64-8948-ae4b484903f9", "type": "concept", "title": "Holding-period return"}, {"id": "0da25460-8d55-4d40-9137-88293e403ce2", "type": "concept", "title": "Real versus nominal return"}], "description": "Students calculate returns consistently across assets and periods."}, {"id": "a6a9d2b1-aed4-401d-83ea-a436715ddd60", "type": "subtopic", "title": "Risk measurement", "children": [{"id": "bf1f0140-a91d-4352-9e94-29e3326b3e2b", "type": "concept", "title": "Variance and standard deviation"}, {"id": "e86ec775-340b-4f6b-83cd-886e79b3a899", "type": "concept", "title": "Downside risk"}, {"id": "07fcfa37-bd39-4321-9e6f-42ed434140c4", "type": "concept", "title": "Drawdowns and tail risk"}], "description": "Risk is more than volatility, but volatility is the starting point."}, {"id": "a067ae8c-f265-4138-a1f5-5c330aff1bdc", "type": "subtopic", "title": "Risk premia", "children": [{"id": "d707f221-64e8-45b0-990f-0cf6ca772543", "type": "concept", "title": "Equity risk premium"}, {"id": "bdc83ccf-d791-4629-9464-a73fad9a7063", "type": "concept", "title": "Credit risk premium"}, {"id": "b0c4eaf2-b2ee-4bc7-885a-f859e9914674", "type": "concept", "title": "Term premium"}], "description": "Investors require compensation for bearing non-diversifiable uncertainty."}]}, {"id": "cc9fe9d4-5896-48fa-8272-a6108053712f", "type": "topic", "title": "Diversification and Portfolio Theory", "description": "This module explains why combining assets can reduce risk and how portfolio choices are evaluated.", "children": [{"id": "a58cbae2-533b-4f89-b90a-d5ac9d5bbd00", "type": "subtopic", "title": "Correlation and covariance", "children": [{"id": "228b2943-3cc5-4992-bac3-a05044c01f2d", "type": "concept", "title": "Correlation"}, {"id": "b0da42f9-3581-4205-af01-b4fbc2b4754b", "type": "concept", "title": "Covariance"}, {"id": "29aa5852-a330-4ea9-a207-dac2de6a08ad", "type": "concept", "title": "Diversification benefits"}], "description": "Portfolio risk depends on how assets move together."}, {"id": "9286c26d-8ff9-494a-9aac-8f415b8860fe", "type": "subtopic", "title": "Mean-variance analysis", "children": [{"id": "d54b0aa4-2cdf-4f14-9169-154abdbb26dd", "type": "concept", "title": "Expected portfolio return"}, {"id": "b640cdf6-b346-4ae4-bbe2-26da2279aca6", "type": "concept", "title": "Portfolio variance"}, {"id": "aea7124d-22e4-4d4a-b9ea-9f71c08305b5", "type": "concept", "title": "Efficient frontier"}], "description": "Students learn the logic of efficient portfolios."}, {"id": "13e1bfa6-5771-4ad0-97a8-236ece6ad230", "type": "subtopic", "title": "Investor objectives", "children": [{"id": "b7b73305-9ded-43c2-8939-24299a545071", "type": "concept", "title": "Risk aversion"}, {"id": "6a80ff4b-3535-43cd-b3aa-e727aebcc488", "type": "concept", "title": "Investment horizon"}, {"id": "70041459-e65a-44e5-a984-a937055aae0e", "type": "concept", "title": "Liquidity and tax constraints"}], "description": "Portfolio choice depends on goals, constraints, and risk tolerance."}]}, {"id": "4320159b-0b03-4a42-9900-4f93973bbb7e", "type": "topic", "title": "CAPM, Factor Models, and Asset Pricing Foundations", "description": "Students learn equilibrium and factor-based approaches to expected return.", "children": [{"id": "b19073b1-f3e0-4ff7-a259-8c082dc3ca76", "type": "subtopic", "title": "CAPM", "children": [{"id": "5dcfd682-6ce0-4ebd-954c-a0252bc6ff08", "type": "concept", "title": "Beta"}, {"id": "6e3634b2-f25b-4dd2-8f3e-f4ae97fdba8e", "type": "concept", "title": "Security market line"}, {"id": "00475cd8-63cd-4114-80cf-64e06830182c", "type": "concept", "title": "Alpha and abnormal return"}], "description": "CAPM links expected return to exposure to market risk."}, {"id": "04b7b1de-eced-403f-bbf6-a9d66c79b8d0", "type": "subtopic", "title": "Factor models", "children": [{"id": "84789f3d-8532-4b35-9d71-e9bfa46e0cf0", "type": "concept", "title": "Size, value, momentum, profitability, and investment factors"}, {"id": "7953ae45-ea72-476c-add7-ccb1a510ce9f", "type": "concept", "title": "Factor exposures"}, {"id": "9d246d20-92f8-4fb3-a70b-d3f803bd6d87", "type": "concept", "title": "Limits of factor models"}], "description": "Modern investing often explains returns with multiple systematic factors."}, {"id": "a1c48fd8-ef7b-4319-ac3d-6fd2a4bd78d1", "type": "subtopic", "title": "Asset pricing interpretation", "children": [{"id": "a6451365-b923-4571-9bed-8e007718dcc4", "type": "concept", "title": "Expected return models"}, {"id": "7107cb75-29c6-4c00-8fdf-8dd1876c2212", "type": "concept", "title": "Cost of equity"}, {"id": "61340fe2-7820-459f-a503-90baf98b08cf", "type": "concept", "title": "Performance attribution preview"}], "description": "Students learn to distinguish risk compensation from mispricing."}]}, {"id": "0ad6d85a-3224-4e85-817a-e4bb70c72ec6", "type": "topic", "title": "Market Efficiency, Behavioral Finance, and Evidence-Based Investing", "description": "This topic balances efficient-markets logic with behavioral limits and empirical anomalies.", "children": [{"id": "473e7723-9d33-4d66-a5db-169cbbe61afc", "type": "subtopic", "title": "Efficient markets", "children": [{"id": "4c60aa4b-dea9-487b-93d5-8eae62963bb1", "type": "concept", "title": "Weak, semi-strong, and strong forms"}, {"id": "1438135b-a483-488e-b86f-dd22a0385df8", "type": "concept", "title": "Random walk intuition"}, {"id": "78ff27ee-19f6-43ed-abef-0032f4bf7ff8", "type": "concept", "title": "Event studies preview"}], "description": "Market efficiency asks how quickly prices reflect information."}, {"id": "b0446106-6a49-49a1-87ad-f9a679785cc3", "type": "subtopic", "title": "Behavioral challenges", "children": [{"id": "0ab27a2d-e4dc-4548-b5a8-2f2044998136", "type": "concept", "title": "Overconfidence"}, {"id": "bb862804-b338-4e72-bab7-d6c78543bf94", "type": "concept", "title": "Loss aversion"}, {"id": "6f9014e7-3d4f-435e-8212-157bae799111", "type": "concept", "title": "Herding and bubbles"}], "description": "Investors are not always perfectly rational or frictionless."}, {"id": "640d7432-9d38-4208-8519-15bdaa07bcd4", "type": "subtopic", "title": "Evidence-based investing", "children": [{"id": "134f0d00-380f-491f-896b-ed8fd54c702e", "type": "concept", "title": "Active versus passive investing"}, {"id": "5ac803e3-a748-40b8-bdf2-99a1cfc13c1b", "type": "concept", "title": "Fees and turnover"}, {"id": "4883967d-a014-4e06-b424-adf4ada6079b", "type": "concept", "title": "Evidence quality and backtests"}], "description": "Students learn to evaluate claims using data, costs, taxes, and incentives."}]}, {"id": "f2d68698-f973-43c5-9995-5e9d28784280", "type": "topic", "title": "Cost of Capital and Capital Structure Introduction", "description": "Students learn how firms estimate required returns and choose between debt, equity, and internal financing.", "children": [{"id": "871f0d1d-c057-4b1b-a3b7-1cf341797453", "type": "subtopic", "title": "Cost of capital", "children": [{"id": "9a542e11-e714-472f-9ec7-188c6aebe0ae", "type": "concept", "title": "Cost of equity"}, {"id": "e652eb89-90af-4cb8-8546-12b127ebac27", "type": "concept", "title": "Cost of debt"}, {"id": "29e47bcd-cdaa-46a0-a94f-d0ec057c0664", "type": "concept", "title": "WACC"}], "description": "The cost of capital is the opportunity cost for project and firm valuation."}, {"id": "c5152d60-743c-409e-afe7-8353ba98f230", "type": "subtopic", "title": "Capital structure", "children": [{"id": "c205deb1-e1b8-43c2-88c7-57ff9d358e18", "type": "concept", "title": "Debt versus equity"}, {"id": "84863d28-7bdd-432e-b3bc-48a58094afd2", "type": "concept", "title": "Tax shields"}, {"id": "96fd6f76-7497-43cc-96ed-76bbc28e5a71", "type": "concept", "title": "Financial distress costs"}], "description": "Students learn why financing mix can matter through taxes, distress, and agency costs."}, {"id": "1aa7b5a9-833b-44fb-abf6-cb75de630894", "type": "subtopic", "title": "Financing lifecycle", "children": [{"id": "5b876c07-a0a6-4d31-b703-38eed136f2c9", "type": "concept", "title": "Internal financing"}, {"id": "c25d8883-48b0-48d8-a383-484dffc27d68", "type": "concept", "title": "Bank debt and bonds"}, {"id": "62829925-6e8d-4d94-86c3-bfcbb5721416", "type": "concept", "title": "Public equity and private capital"}], "description": "Different firms use different financing at different stages."}]}, {"id": "830c29a6-5088-4635-b5dc-e3de91909a2e", "type": "topic", "title